// Bring in Verus’s verified Vec and quantifiers
use builtin::*;
use pervasive::vec::Vec;

verus! {

  /// Insert `delimiter` between every pair of consecutive elements in `numbers`.
  ///
  /// If `numbers.len() ≤ 1`, returns `numbers` unchanged.
  /// Otherwise returns a new Vec of length `2⋅n−1` where:
  ///   • for each i < n, result[2*i] = numbers[i]
  ///   • for each i < n−1, result[2*i+1] = delimiter
  #[verus::verifier]
  fn insert_delimiter(numbers: Vec<i8>, delimiter: i8) -> Vec<i8>
    ensures |res: Vec<i8>|
      // length is either unchanged (for n≤1) or exactly 2*n−1
      res.len() == if numbers.len() <= 1 {
        numbers.len()
      } else {
        2 * numbers.len() - 1
      }
      &&
      // even positions copy the input, odd positions are the delimiter
      forall(|j: usize| j < res.len() ==>
        if j % 2 == 0 {
          res[j] == numbers[j / 2]
        } else {
          res[j] == delimiter
        }
      )
  {
    let n = numbers.len();
    // short‐circuit in the trivial cases
    if n <= 1 {
      numbers
    } else {
      // build the longer vector
      let mut res = Vec::new();
      res.reserve(2 * n - 1);

      let mut i = 0;
      // loop: process one number (and maybe one delimiter) per iteration
      while i < n
        invariant i <= n
        // invariant on the current length of `res`:
        //   if we've processed i items and i<n, we've pushed exactly 2⋅i elements
        //   if i==n, we've finished with 2⋅n−1 elements
        invariant
          (i < n && res.len() == 2 * i)
          ||
          (i == n && res.len() == 2 * n - 1)
        // invariant preserving the "even→number / odd→delimiter" pattern
        invariant forall(|j: usize| j < res.len() ==>
          if j % 2 == 0 {
            res[j] == numbers[j / 2]
          } else {
            res[j] == delimiter
          }
        )
        // terminate because `i` grows towards `n`
        decreases n - i
      {
        // push the next original element
        res.push(numbers[i]);
        // if there is still another element afterwards, push the delimiter
        if i + 1 < n {
          res.push(delimiter);
        }
        i += 1;
      }

      res
    }
  }
}